import json
import re
from typing import Any, Dict, List, Literal, Optional, Union
from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator


class FunctionCall(BaseModel):
    """Function call detail requested by the model."""

    model_config = ConfigDict(extra="forbid")

    name: str = Field(..., min_length=1, max_length=64, description="Name of the function to call.")
    arguments: str = Field(default="", description="JSON-formatted string of arguments.")


class ChatCompletionMessageToolCall(BaseModel):
    """Tool call generated by the model."""

    model_config = ConfigDict(extra="forbid")

    id: str = Field(..., min_length=1, description="Tool call identifier.")
    type: Literal["function"] = "function"
    function: FunctionCall


class FunctionDefinition(BaseModel):
    """Definition of a function tool callable by the model."""

    model_config = ConfigDict(extra="forbid")

    name: str = Field(..., min_length=1, max_length=64, description="Name of the function.")
    description: Optional[str] = Field(default=None, max_length=1024, description="Description of the function.")
    parameters: Optional[Dict[str, Any]] = Field(default=None, description="JSON Schema for function arguments.")
    strict: Optional[bool] = Field(default=None, description="Whether to enforce strict schema adherence.")

    @field_validator("name")
    @classmethod
    def validate_function_name(cls, v: str) -> str:
        if not re.match(r"^[a-zA-Z0-9_-]{1,64}$", v):
            raise ValueError(
                f"Invalid function name '{v}'. Must be 1-64 characters matching ^[a-zA-Z0-9_-]+$."
            )
        return v

    @field_validator("parameters")
    @classmethod
    def validate_parameters_schema(cls, v: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        if v is None:
            return None
        if not isinstance(v, dict):
            raise ValueError("Function parameters must be a valid JSON Schema dictionary.")
        # Check size limit: max 32KB
        raw_size = len(json.dumps(v))
        if raw_size > 32_768:
            raise ValueError(f"Function parameters schema size ({raw_size} bytes) exceeds maximum limit of 32768 bytes.")
        schema_type = v.get("type")
        if schema_type is not None and schema_type != "object":
            raise ValueError(f"Root schema type for function parameters must be 'object', got '{schema_type}'.")
        return v


class ChatCompletionTool(BaseModel):
    """Tool specification for model execution."""

    model_config = ConfigDict(extra="forbid")

    type: Literal["function"] = "function"
    function: FunctionDefinition


class ChatCompletionNamedFunction(BaseModel):
    model_config = ConfigDict(extra="forbid")
    name: str = Field(..., min_length=1, max_length=64)


class ChatCompletionNamedToolChoice(BaseModel):
    model_config = ConfigDict(extra="forbid")
    type: Literal["function"] = "function"
    function: ChatCompletionNamedFunction


class ChatMessage(BaseModel):
    """Chat message schema supporting plain-text and tool-augmented conversations."""

    model_config = ConfigDict(extra="forbid")

    role: Literal["system", "user", "assistant", "tool"] = Field(
        ...,
        description="The role of the message author.",
    )
    content: Optional[str] = Field(
        default=None,
        description="The plain-text content of the message.",
    )
    tool_call_id: Optional[str] = Field(
        default=None,
        description="Tool call identifier associated with this tool result message.",
    )
    tool_calls: Optional[List[ChatCompletionMessageToolCall]] = Field(
        default=None,
        description="Tool calls generated by the assistant.",
    )

    @model_validator(mode="after")
    def validate_message_fields(self) -> "ChatMessage":
        if self.role in ("system", "user"):
            if not self.content or not self.content.strip():
                raise ValueError(f"Message with role '{self.role}' must have non-empty content.")
        elif self.role == "tool":
            if not self.tool_call_id or not self.tool_call_id.strip():
                raise ValueError("Message with role 'tool' must specify a non-empty 'tool_call_id'.")
            if self.content is None:
                raise ValueError("Message with role 'tool' must specify 'content'.")
        elif self.role == "assistant":
            if self.content is None and not self.tool_calls:
                raise ValueError("Assistant message must contain either 'content' or 'tool_calls'.")
            if self.content is not None and not self.content.strip() and not self.tool_calls:
                raise ValueError("Message content cannot be empty or whitespace only.")
        return self


class ChatCompletionRequest(BaseModel):
    """Request payload for /v1/chat/completions."""

    model_config = ConfigDict(extra="forbid")

    model: str = Field(
        ...,
        min_length=1,
        description="The target model ID. Must belong to the configured allowed_models.",
    )
    messages: List[ChatMessage] = Field(
        ...,
        min_length=1,
        description="List of messages comprising the conversation so far.",
    )
    temperature: Optional[float] = Field(
        default=1.0,
        ge=0.0,
        le=2.0,
        description="Sampling temperature between 0 and 2.",
    )
    max_completion_tokens: Optional[int] = Field(
        default=None,
        gt=0,
        description="Maximum number of tokens to generate. Must be a positive integer.",
    )
    stream: Optional[bool] = Field(
        default=False,
        description="Stream responses via Server-Sent Events (SSE).",
    )
    allow_failover: Optional[bool] = Field(
        default=None,
        description="Optional request-level override to enable or disable multi-provider failover.",
    )
    tools: Optional[List[ChatCompletionTool]] = Field(
        default=None,
        description="A list of tools the model may call.",
    )
    tool_choice: Optional[Union[Literal["none", "auto", "required"], ChatCompletionNamedToolChoice]] = Field(
        default=None,
        description="Controls which (if any) tool is called by the model.",
    )

    @field_validator("model")
    @classmethod
    def validate_model_not_empty(cls, v: str) -> str:
        if not v or not v.strip():
            raise ValueError("Model name cannot be empty or whitespace only.")
        return v.strip()

    @field_validator("tools")
    @classmethod
    def validate_tools_list(cls, v: Optional[List[ChatCompletionTool]]) -> Optional[List[ChatCompletionTool]]:
        if v is None:
            return None
        if len(v) > 32:
            raise ValueError(f"Number of tools ({len(v)}) exceeds maximum allowed limit of 32.")
        names = set()
        for t in v:
            if t.function.name in names:
                raise ValueError(f"Duplicate tool name '{t.function.name}' in tool definitions.")
            names.add(t.function.name)
        return v

    @model_validator(mode="after")
    def validate_tool_choice(self) -> "ChatCompletionRequest":
        if self.tool_choice is not None and self.tool_choice != "none":
            if not self.tools:
                raise ValueError("tool_choice cannot be specified without providing 'tools'.")
            if isinstance(self.tool_choice, ChatCompletionNamedToolChoice):
                func_name = self.tool_choice.function.name
                tool_names = [t.function.name for t in self.tools]
                if func_name not in tool_names:
                    raise ValueError(
                        f"tool_choice specifies function '{func_name}' which is not in provided tools."
                    )
        return self


class UsageInfo(BaseModel):
    """Token usage reporting with explicit provenance."""

    model_config = ConfigDict(extra="forbid")

    prompt_tokens: Optional[int] = None
    completion_tokens: Optional[int] = None
    total_tokens: Optional[int] = None
    is_mock_estimate: bool = Field(
        default=False,
        description="True if token counts are deterministic mock estimates rather than real provider reports.",
    )
    usage_source: str = Field(
        default="unavailable",
        description="Provenance of token usage: 'provider_reported', 'mock_estimated', or 'unavailable'.",
    )


class ChatChoiceMessage(BaseModel):
    """The generated message from the assistant."""

    model_config = ConfigDict(extra="forbid")

    role: str = "assistant"
    content: Optional[str] = None
    tool_calls: Optional[List[ChatCompletionMessageToolCall]] = None


class ChatChoice(BaseModel):
    """A single completion choice."""

    model_config = ConfigDict(extra="forbid")

    index: int = 0
    message: ChatChoiceMessage
    finish_reason: Optional[str] = "stop"


class ChatCompletionResponse(BaseModel):
    """OpenAI-compatible chat completion response."""

    model_config = ConfigDict(extra="forbid")

    id: str
    object: str = "chat.completion"
    created: int
    model: str
    choices: List[ChatChoice]
    usage: UsageInfo


class ChatCompletionChunkDeltaFunctionCall(BaseModel):
    """Incremental function call fragment."""

    model_config = ConfigDict(extra="forbid")

    name: Optional[str] = None
    arguments: Optional[str] = None


class ChatCompletionChunkDeltaToolCall(BaseModel):
    """Incremental tool call fragment."""

    model_config = ConfigDict(extra="forbid")

    index: int = 0
    id: Optional[str] = None
    type: Optional[Literal["function"]] = "function"
    function: Optional[ChatCompletionChunkDeltaFunctionCall] = None


class ChatCompletionChunkDelta(BaseModel):
    """Incremental delta content generated by the assistant."""

    model_config = ConfigDict(extra="forbid")

    role: Optional[Literal["assistant", "system", "user", "tool"]] = None
    content: Optional[str] = None
    tool_calls: Optional[List[ChatCompletionChunkDeltaToolCall]] = None


class ChatCompletionChunkChoice(BaseModel):
    """A single streaming chunk choice."""

    model_config = ConfigDict(extra="forbid")

    index: int = 0
    delta: ChatCompletionChunkDelta
    finish_reason: Optional[str] = None


class ChatCompletionChunk(BaseModel):
    """OpenAI-compatible streaming chunk object."""

    model_config = ConfigDict(extra="forbid")

    id: str
    object: Literal["chat.completion.chunk"] = "chat.completion.chunk"
    created: int
    model: str
    choices: List[ChatCompletionChunkChoice]
    usage: Optional[UsageInfo] = None

    def to_sse_event(self) -> str:
        """Format chunk into an OpenAI-compatible Server-Sent Event data line."""
        return f"data: {self.model_dump_json(exclude_none=True)}\n\n"


class UsageSummaryResponse(BaseModel):
    """Aggregated usage and cost summary scoped to the authenticated client."""

    model_config = ConfigDict(extra="forbid")

    client_id: str
    total_requests: int
    successful_requests: int
    failed_requests: int
    cache_hits: int = 0
    cache_misses: int = 0
    provider_counts: Dict[str, int]
    known_input_tokens: int
    known_output_tokens: int
    known_total_tokens: int
    unavailable_usage_count: int
    mock_requests_count: int
    estimated_cloud_cost: float
    unknown_cost_count: int
    currency: str
    avg_gateway_latency_ms: float
    avg_provider_latency_ms: float
